    /**
     * Tests getting all ForecastLines.
     *
     * @return    Collection
     */
    public List<ForecastLine> testGetAll() throws Throwable {
    LOGGER.info( "ForecastLineTest:testGetAll() - Retrieving Collection of ForecastLines:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all ForecastLine : " );
    List<ForecastLine> collection  = null;

    try {
        // call the static get method on the ForecastLineService
        collection = service.getAllForecastLine();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            ForecastLine currEntity  = null;
            Iterator<ForecastLine> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getForecastLineId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

